  app.route("/v1/overview", createOverviewRoutes({ db }));
  app.route("/v1/settlement", createSettlementRoutes({ db, chain: options.chain ?? null }));
  if (options.webRoot) {
    app.use("/*", serveStatic({ root: options.webRoot }));
  }
